/* Types */
/**
 *  What the author is doing when KARA engages: where it must be able to
 *  return to.
 */
export type Activity = "writing" | "reviewing";

/**
 *  The harness kinds with a defined adapter (SPEC 8.3a). `L0` is the file
 *  channel any producer — including a human pasting into a web chat — can serve.
 */
export type AdapterKind = "l0" | "codex" | "claude-code" | "pi" | "kimi-code" | "hermes";

/**  One Agent as the surface lists it: the profile plus its channel's facts. */
export type AgentDto = {
	id: string,
	name: string,
	connectionId: string | null,
	hasPersona: boolean,
	/**
	 *  The persona text itself, so the edit form can prefill. `None` when the
	 *  profile carries none — the same state `has_persona` reports.
	 */
	persona: string | null,
	/**
	 *  The agent's extra argv (model, effort — argv by nature), so the edit
	 *  form can show what launches with this agent. Empty by default.
	 */
	argv: string[],
	channel: string,
	version: string,
};

/**
 *  One Agent the author works with: a name, the channel it
 *  runs on (`None` = the L0 file channel), and an optional persona — one
 *  Markdown identity injected right after the contract on every round.
 */
export type AgentProfile = {
	id: Id,
	name: string,
	/**  The connection this agent runs on; `None` is the L0 file channel. */
	connection_id?: Id | null,
	/**  The identity text, injected into the request after the contract. */
	persona?: string | null,
	/**
	 *  Extra argv handed to the harness at launch, after the connection's
	 *  own. Model and effort settings are argv by nature — naming them one by
	 *  one would enum-chase every CLI flag. Validated against a denylist at
	 *  upsert, never at launch: a refusal must reach the author while he is
	 *  editing, not as a failed run.
	 */
	argv?: string[],
};

/**
 *  One agent's reading of one document: rounds read, the baseline it last
 *  stood on, and whether the current head has left that baseline behind.
 *  A lag count needs the pinned-revision chain (SPEC 10.1), which does not
 *  exist yet — the honest shape today is a stale flag, not a number.
 */
export type AgentReadingDto = AgentReadingDto_Serialize | AgentReadingDto_Deserialize;

/**
 *  One agent's reading of one document: rounds read, the baseline it last
 *  stood on, and whether the current head has left that baseline behind.
 *  A lag count needs the pinned-revision chain (SPEC 10.1), which does not
 *  exist yet — the honest shape today is a stale flag, not a number.
 */
export type AgentReadingDto_Deserialize = {
	agentId: string,
	document: string,
	rounds: number,
	lastBaseline: string,
	lastAt: string,
	currentHead: string | null,
	stale: boolean,
};

/**
 *  One agent's reading of one document: rounds read, the baseline it last
 *  stood on, and whether the current head has left that baseline behind.
 *  A lag count needs the pinned-revision chain (SPEC 10.1), which does not
 *  exist yet — the honest shape today is a stale flag, not a number.
 */
export type AgentReadingDto_Serialize = {
	agentId: string,
	document: string,
	rounds: number,
	lastBaseline: string,
	lastAt: string,
	currentHead: string | null,
	stale: boolean,
};

export type AnnotationAnchorState = "anchored" | "drifted";

export type AnnotationDto = {
	id: string,
	document: string,
	blockId: string,
	start: number,
	end: number,
	quote: string,
	kind: AnnotationKind,
	body: string | null,
	createdAt: string,
	updatedAt: string,
	anchorState: AnnotationAnchorState,
};

export type AnnotationKind = "highlight" | "comment";

